def ref_change_base(x: int, base: int) -> str:
    if x == 0:
        return "0"
    digits = []
    v = x
    while v > 0:
        digits.append(str(v % base))
        v //= base
    return "".join(reversed(digits))

@given(x=st.integers(min_value=0, max_value=5000), base=st.integers(min_value=2, max_value=9))
def test_prefix_equals_quotient_representation(x, base):
    # metamorphic: dropping last digit gives representation of x // base (except x < base)
    s = change_base(x, base)
    if x >= base:
        assert s[:-1] == change_base(x // base, base)
    else:
        assert len(s) == 1
